@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        var direction = extraData.getDirection();
        float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
        float yaw = (float) Math.toRadians(yRot);
        Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
        Vec3 up = left.cross(direction);
        for(int i = 0; i < 6; i++) {
            float upwardsOffset = i*0.4f;
            float slashOffset = 2 - i*0.6f;
            for (int j = 0; j < 2; j++) {
                float spinOffset = extraData.getSlashRotation() + Easing.SINE_IN_OUT.asWeighedRandom(random, -0.25f, 0.25f) + (extraData.isMirrored() ? 3.14f : 0);

                var slashPosition = positionData.getAsVector().add(direction.scale(slashOffset)).add(up.scale(upwardsOffset));

                var slash = WeaponParticleEffects.spawnSlashParticle(level, slashPosition, MalumParticles.SLASH, colorData);
                slash.getBuilder()
                        .setSpinData(SpinParticleData.create(0).setSpinOffset(spinOffset).build())
                        .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 2.5f, 3f)).build())
                        .setMotion(direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.2f, 0.4f)).add(0, 0.8f, 0))
                        .setLifetime(3+i)
                        .setLifeDelay(i/2)
                        .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(direction));
                slash.spawnParticles();
            }
        }
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, NetworkedParticleEffectExtraData extraData) {
        float angle = random.nextFloat() * 6.28f;
        float x = Mth.sin(angle);
        float z = Mth.cos(angle);
        Vec3 direction = new Vec3(x, 0, z);

        ParticleEffectSpawner slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), random.nextBoolean() ? MalumParticles.THIN_ROUNDABOUT_SLASH : MalumParticles.ROUNDABOUT_SLASH, colorData);
        int lifetime = Easing.SINE_IN_OUT.asWeighedRandom(random, 8, 12);
        int directionScalar = random.nextBoolean() ? -1 : 1;
        slash.getBuilder()
                .setSpinData(SpinParticleData.create(0).randomSpinOffset(random).build())
                .setLifetime(lifetime)
                .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 2f, 3f)).build())
                .setMotion(direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.02f, 0.05f)))
                .setRandomOffset(0.5f)
                .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(direction.scale(directionScalar)));
        slash.spawnParticles();
        slash.getBuilder()
                .setTransparencyData(GenericParticleData.create(0.6f, 0.3f).build())
                .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 1.5f, 2f)).build())
                .setLifeDelay(lifetime);
        slash.spawnParticles();
        slash.getBuilder()
                .setTransparencyData(GenericParticleData.create(0.3f, 0f).build())
                .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 1.2f, 1.6f)).build())
                .setLifeDelay(lifetime*2);
        slash.spawnParticles();
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, WeaponParticleEffectData extraData) {
        var direction = extraData.getDirection();
        float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
        float yaw = (float) Math.toRadians(yRot);
        Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));



        var roundaboutSlash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.ROUNDABOUT_SLASH, colorData);
        roundaboutSlash.getBuilder()
                .setSpinData(SpinParticleData.create(0).setSpinOffset(extraData.getSlashRotation() + (extraData.isMirrored() ? 3.14f : 0)).build())
                .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 4f, 6f)).build())
                .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(direction));

        for (int i = 0; i < 4; i++) {
            var transparency = 1f - i * 0.3f;
            roundaboutSlash.getBuilder().setTransparencyData(GenericParticleData.create(transparency).build()).setLifeDelay(i * 2);
            roundaboutSlash.spawnParticles();
        }

        for (int i = 0; i < 6; i++) {
            float angle = i / 6f * 6.28f;
            var slashDirection = left.scale(Math.sin(angle))
                    .add(direction.scale(Math.cos(angle)))
                    .normalize();
            var slash = WeaponParticleEffects.spawnSlashParticle(level, positionData.getAsVector(), MalumParticles.SLASH, colorData);
            slash.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset(extraData.getSlashRotation() + (extraData.isMirrored() ? 3.14f : 0)).build())
                    .setScaleData(GenericParticleData.create(Easing.SINE_IN_OUT.asWeighedRandom(random, 4f, 6f)).build())
                    .setMotion(slashDirection.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.7f)))
                    .setBehavior(PointyDirectionalParticleBehavior.pointyDirectional(slashDirection));

            for (int j = 0; j < 3; j++) {

                var transparency = 1f - j * 0.4f;
                slash.getBuilder()
                        .setTransparencyData(GenericParticleData.create(transparency).build())
                        .setLifeDelay(j * 2);
                slash.spawnParticles();

            }
        }
    }
